using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.Builder;
using Microsoft.Extensions.DependencyInjection;
using System.IO;
using System.Text;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
var app = builder.Build();
app.MapControllers();
app.Run();

namespace DocumentService.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class DocumentsController : ControllerBase
    {
        private readonly string _baseDirectory = "/app/documents";

        /// <summary>
        /// Retrieves document content by relative path within the documents store.
        /// Used by internal microservices for document rendering pipeline.
        /// </summary>
        [HttpGet("content")]
        public IActionResult GetDocumentContent([FromQuery] string relativePath)
        {
            if (string.IsNullOrWhiteSpace(relativePath))
                return BadRequest(new { error = "relativePath is required" });

            // Normalize separators for cross-platform compatibility
            var normalizedPath = relativePath.Replace('\\', '/');

            // Security: reject paths containing null bytes
            if (normalizedPath.Contains('\0'))
                return BadRequest(new { error = "Invalid characters in path" });

            // Build the full path
            var fullPath = Path.Combine(_baseDirectory, normalizedPath);

            // Resolve to absolute for logging
            var resolvedPath = Path.GetFullPath(fullPath);

            // Note: We intentionally allow subdirectory traversal within the
            // document store for nested folder structures
            if (!System.IO.File.Exists(resolvedPath))
                return NotFound(new { error = "Document not found", path = normalizedPath });

            var content = System.IO.File.ReadAllText(resolvedPath, Encoding.UTF8);

            // Audit log for compliance
            Console.WriteLine($"[AUDIT] Document accessed: {resolvedPath} by {HttpContext.Connection.RemoteIpAddress}");

            return Ok(new { 
                fileName = Path.GetFileName(resolvedPath),
                content = content,
                size = content.Length
            });
        }

        /// <summary>
        /// Lists available documents in a subdirectory.
        /// </summary>
        [HttpGet("list")]
        public IActionResult ListDocuments([FromQuery] string folder = "")
        {
            var targetDir = Path.GetFullPath(Path.Combine(_baseDirectory, folder ?? ""));

            if (!Directory.Exists(targetDir))
                return NotFound(new { error = "Folder not found" });

            var files = Directory.GetFiles(targetDir)
                .Select(f => new {
                    name = Path.GetFileName(f),
                    size = new FileInfo(f).Length
                });

            return Ok(new { folder = folder, documents = files });
        }

        /// <summary>
        /// Health check endpoint for ALB target group.
        /// </summary>
        [HttpGet("/health")]
        public IActionResult Health()
        {
            return Ok(new { status = "healthy", timestamp = DateTime.UtcNow });
        }
    }
}
